// Exponential backoff with full jitter
async function withRetry(fn, { attempts = 4, base = 100, cap = 2000 } = {}) {
  for (let i = 0; ; i++) {
    try { return await fn(); }
    catch (e) {
      if (i === attempts - 1 || !isRetryable(e)) throw e;   // 4xx: don't retry
      const delay = Math.random() * Math.min(cap, base * 2 ** i);
      await new Promise((r) => setTimeout(r, delay));
    }
  }
}
